// Render the weekly report HTML from weekly_lead_report() JSON.
const r = $input.first().json.report || {};
const FUENTE = { inmuebles24: '\uD83D\uDFE0 Inmuebles24', easybroker: '\uD83D\uDD35 EasyBroker' };
const recibidos = r.recibidos || 0;
const reclamados = r.reclamados || 0;
const noAt = r.no_atendidos || 0;
const enTurno = r.asesores_en_turno || 0;
const fuente = r.por_fuente || {};
const porAsesor = r.reclamados_por_asesor || [];
const lista = r.no_atendidos_lista || [];
const dias = r.days || 7;
const tasa = recibidos ? Math.round(100 * reclamados / recibidos) : 0;
const inm = fuente.inmuebles24 || 0;
const eb = fuente.easybroker || 0;

const card = (label, value, color) =>
  `<td style="padding:0 6px"><div style="background:${color}1a;border:2px solid ${color};border-radius:10px;padding:14px;text-align:center"><div style="font-size:30px;font-weight:800;color:${color}">${value}</div><div style="font-size:12.5px;color:#444;margin-top:2px">${label}</div></div></td>`;

const asesorRows = porAsesor.length
  ? porAsesor.map(a => `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">${a.asesor || '?'}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;text-align:right;font-weight:700">${a.n || 0}</td></tr>`).join('')
  : '<tr><td colspan="2" style="padding:6px 12px;color:#888">(nadie reclam\u00f3)</td></tr>';

const listaRows = lista.length
  ? lista.map((l, i) => `<tr><td style="padding:7px 10px;border-bottom:1px solid #eee">${i+1}</td><td style="padding:7px 10px;border-bottom:1px solid #eee;font-weight:600">${l.nombre || ''}</td><td style="padding:7px 10px;border-bottom:1px solid #eee">${FUENTE[l.fuente] || l.fuente || ''}</td><td style="padding:7px 10px;border-bottom:1px solid #eee">${l.telefono || ''}</td><td style="padding:7px 10px;border-bottom:1px solid #eee;color:#666">${l.propiedad || '\u2014'}</td><td style="padding:7px 10px;border-bottom:1px solid #eee;color:#666">${l.fecha || ''}</td></tr>`).join('')
  : '<tr><td colspan="6" style="padding:10px;color:#0a7d4d">\uD83C\uDF89 Todos los leads fueron atendidos.</td></tr>';

const alerta = enTurno === 0
  ? '<div style="margin:18px 0;padding:14px 16px;background:#ffeede;border:2px solid #b8500a;border-radius:8px;color:#7a3606;font-size:14px">\u26A0\uFE0F <b>0 asesores en turno</b> esta semana \u2014 por eso casi todos los leads se quedaron sin atender. Hay que poner asesores en turno (calendario de guardias).</div>'
  : '';

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"></head><body style="margin:0;background:#f4f1ea;font-family:'Segoe UI',Roboto,Arial,sans-serif;color:#11161c"><div style="max-width:720px;margin:0 auto;padding:24px"><div style="background:#11161c;color:#fff;border-radius:12px;padding:22px 24px;margin-bottom:18px"><div style="font-size:22px;font-weight:800">\uD83D\uDCCA Reporte semanal de leads \u2014 BYG Real Estate</div><div style="opacity:.8;font-size:14px;margin-top:4px">\u00daltimos ${dias} d\u00edas</div></div><table style="width:100%;border-collapse:separate;margin-bottom:8px"><tr>${card('Recibidos', recibidos, '#3b5bff')}${card('Reclamados', reclamados, '#0a7d4d')}${card('Sin atender', noAt, '#e8501e')}${card('Tasa atenci\u00f3n', tasa + '%', '#11161c')}</tr></table>${alerta}<table style="width:100%;border-collapse:collapse;margin:18px 0"><tr><td style="width:50%;vertical-align:top;padding-right:8px"><div style="font-weight:700;margin-bottom:6px">Por fuente</div><div style="background:#fff;border:2px solid #11161c;border-radius:10px;padding:10px 14px;font-size:14px">\uD83D\uDFE0 Inmuebles24: <b>${inm}</b><br>\uD83D\uDD35 EasyBroker: <b>${eb}</b></div></td><td style="width:50%;vertical-align:top;padding-left:8px"><div style="font-weight:700;margin-bottom:6px">Reclamados por asesor</div><table style="width:100%;background:#fff;border:2px solid #11161c;border-radius:10px;border-collapse:collapse;font-size:14px">${asesorRows}</table></td></tr></table><div style="font-weight:700;font-size:16px;margin:22px 0 8px">\u274C Leads sin atender (${noAt}) \u2014 a recuperar</div><table style="width:100%;background:#fff;border:2px solid #11161c;border-radius:10px;border-collapse:collapse;font-size:13.5px"><tr style="background:#11161c;color:#fff"><th style="padding:8px 10px;text-align:left">#</th><th style="padding:8px 10px;text-align:left">Cliente</th><th style="padding:8px 10px;text-align:left">Fuente</th><th style="padding:8px 10px;text-align:left">Tel\u00e9fono</th><th style="padding:8px 10px;text-align:left">Propiedad</th><th style="padding:8px 10px;text-align:left">Fecha</th></tr>${listaRows}</table><div style="color:#888;font-size:12px;margin-top:22px;border-top:1px solid #ddd;padding-top:10px">Generado autom\u00e1ticamente \u00b7 Sistema de atenci\u00f3n de leads BYG</div></div></body></html>`;

return [{ json: { subject: `\uD83D\uDCCA Reporte semanal de leads BYG \u2014 ${noAt} sin atender`, html } }];
